import itertools, random, json, sys
from problems import VertexCover, Sat
import reduce

def solve_vertex_cover(inst):
    n = inst['n']
    edges = inst['edges']
    k = inst['k']
    if k < 0:
        return False
    # trivial yes cases
    if not edges:
        return True
    if k >= n:
        return True
    # brute force subsets up to k
    vertices = list(range(n))
    for r in range(k+1):
        for subset in itertools.combinations(vertices, r):
            covered = True
            s = set(subset)
            for u,v in edges:
                if u not in s and v not in s:
                    covered = False
                    break
            if covered:
                return True
    return False

def solve_sat(inst):
    m = inst['num_vars']
    clauses = inst['clauses']
    # empty clause means unsat
    for clause in clauses:
        if not clause:
            return False
    for bits in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            clause_ok = False
            for lit in clause:
                var = abs(lit) - 1
                val = bits[var]
                if lit > 0 and val:
                    clause_ok = True
                    break
                if lit < 0 and not val:
                    clause_ok = True
                    break
            if not clause_ok:
                ok = False
                break
        if ok:
            return True
    return False

def random_instance(max_n=5, max_k=5, edge_prob=0.4):
    n = random.randint(0, max_n)
    vertices = list(range(n))
    edges = []
    for u in vertices:
        for v in range(u+1, n):
            if random.random() < edge_prob:
                edges.append([u, v])
    k = random.randint(-1, max_k)
    return {'n': n, 'edges': edges, 'k': k}

def main():
    random.seed(0)
    total = 0
    passed = 0
    for _ in range(200):
        src = random_instance()
        VertexCover.validate(src)
        sat_inst = reduce.reduce(src)
        Sat.validate(sat_inst)
        src_ans = solve_vertex_cover(src)
        sat_ans = solve_sat(sat_inst)
        total += 1
        if src_ans == sat_ans:
            passed += 1
        else:
            print('Mismatch!')
            print('src', src)
            print('sat', sat_inst)
            print('src_ans', src_ans, 'sat_ans', sat_ans)
            sys.exit(1)
    print('All tests passed', passed, '/', total)
    # write verdict
    verdict = {'verified': True, 'tests_run': total, 'tests_passed': passed}
    with open('verdict.json', 'w') as f:
        json.dump(verdict, f)

if __name__ == '__main__':
    main()
EOF"}

